"""rules-b am20's red-first, live: the new conformance cases (`test_edges_among_at_scale.py`) run
against `edges_among` and its renderer exactly as main had them before ADR-124 Amendment 20 (both
texts below, from main 0245427), then the files restored. Run from OspreyFlow_Core under the lease
(`stack_lease.sh remote`). Expected: the case past the compile wall red at 25,000 ids."""

import os
import subprocess
import tempfile

FILES = {
    "packages/adapters/graph_arcadedb/builders.py": ('def render_edges_among_gremlin(\n    record_ids: Sequence[str],\n    access: AccessFilter,\n    principal: Principal,\n    edge_types: list[str] | None = None,\n) -> str:\n    """One chunk of `GraphPort.edges_among` (ADR-098 decision 1; ADR-124 Amendment 20): from the\n    vertices at `record_ids` (one chunk of the asked-for ids, resolved by\n    `render_record_id_lookup_sql`), their outgoing links, each row the link and its far end\'s id.\n    The adapter keeps a row only where that id was asked for. The access step is on the tail, the\n    link and the head, so a hidden link, or a link to a hidden node, gives no row.\n\n    Never `has("id", within(...))`: that read every vertex in the store for each id list, and with\n    every id in the text twice, ArcadeDB could not compile the script past some 10,000 to 25,000 ids\n    ("Class too large", measured 14 November 2026). The text now holds one chunk\'s record ids only.\n    For no record ids the query is still rendered, as `render_get_nodes_gremlin`\'s is, so an absent\n    id costs the round trip a hidden one does."""\n    has_access = access.gremlin_has_step(principal)\n    label_filter = ""\n    if edge_types:\n        physical = [label for t in edge_types for label in physical_edge_labels(t)]\n        label_filter = f".hasLabel({groovy_args_literal(physical)})"\n    source = (\n        "g.V().limit(0)"\n        if not record_ids\n        else f"g.V({groovy_string_list_literal(list(record_ids))})"\n    )\n    return (\n        f"{source}.{has_access}"\n        f".outE(){label_filter}.{has_access}.dedup().as(\'e\')"\n        f".inV().{has_access}.as(\'t\')"\n        ".select(\'e\',\'t\').by(elementMap()).by(values(\'id\'))"\n    )\n\n\n', 'def render_edges_among_gremlin(\n    node_ids: Sequence[str],\n    access: AccessFilter,\n    principal: Principal,\n    edge_types: list[str] | None = None,\n) -> str:\n    """Every edge with both ends in `node_ids` (ADR-098 decision 1), each once: from each node in\n    the set, its outgoing edges, kept when their head is in the set too. The access step is on the\n    tail, the edge and the head, so a hidden edge, or an edge to a hidden node, leaves no trace."""\n    has_access = access.gremlin_has_step(principal)\n    ids = groovy_string_list_literal(list(node_ids))\n    label_filter = ""\n    if edge_types:\n        physical = [label for t in edge_types for label in physical_edge_labels(t)]\n        label_filter = f".hasLabel({groovy_args_literal(physical)})"\n    return (\n        f\'g.V().has("id",within({ids})).{has_access}\'\n        f".outE(){label_filter}.{has_access}"\n        f\'.where(inV().has("id",within({ids})).{has_access})\'\n        ".dedup().elementMap()"\n    )\n\n\n'),
    "packages/adapters/graph_arcadedb/adapter.py": ('    async def edges_among(\n        self,\n        node_ids: Sequence[str],\n        principal: Principal,\n        edge_types: list[str] | None = None,\n    ) -> list[Edge]:\n        """ADR-124 Amendment 20: each chunk of the ids is resolved to record ids through each vertex\n        type\'s unique `id` index (as `get_nodes` is), the links leaving those records are read with\n        the access step on both ends and the link, and a link is kept where its far end\'s id was\n        asked for. Each link is reached from its own source alone, and each source record is in one\n        chunk, so a link across two chunks is found once, with no merging by id: two links of\n        different types may hold one id, and both are listed, as before. Every chunk\'s query is\n        sent, so the round trips depend on how many ids were asked, never on which of them the\n        reader may see (rule 3)."""\n        if isinstance(node_ids, str):\n            raise TypeError("node_ids must be a sequence of ids, not a single string")\n        wanted = set(node_ids)\n        if len(wanted) < 2:\n            return []\n        types = await self._types_with_unique_id("vertex")\n        found: list[Edge] = []\n        for chunk in _id_chunks(sorted(wanted)):\n            rids = await self._record_ids(types, chunk)\n            query = render_edges_among_gremlin(rids, self._access, principal, edge_types)\n            found += [\n                edge_from_element_map(row["e"], principal)\n                for row in await self._client.gremlin(query)\n                if row["t"] in wanted\n            ]\n        return found\n\n', '    async def edges_among(\n        self,\n        node_ids: Sequence[str],\n        principal: Principal,\n        edge_types: list[str] | None = None,\n    ) -> list[Edge]:\n        if len(set(node_ids)) < 2:\n            return []\n        records = await self._client.gremlin(\n            render_edges_among_gremlin(sorted(set(node_ids)), self._access, principal, edge_types)\n        )\n        return [edge_from_element_map(r, principal) for r in records]\n\n'),
}
TESTS = "../OspreyFlow_Build/tests/conformance/graph_port/test_edges_among_at_scale.py"

originals = {path: open(path).read() for path in FILES}
try:
    for path, (now, before) in FILES.items():
        assert originals[path].count(now) == 1, path
        open(path, "w").write(originals[path].replace(now, before))
    env = dict(os.environ, PYTHONPYCACHEPREFIX=tempfile.mkdtemp(prefix="red-first-pyc-"))
    r = subprocess.run([".venv/bin/pytest", "-c", "../OspreyFlow_Build/pytest.ini", "-q", "-s", "-p",
                        "no:cacheprovider", "-rfE", TESTS], capture_output=True, text=True, env=env)
    for line in r.stdout.splitlines():
        if line.startswith(("FAILED", "ERROR", "ADR-124")) or " passed" in line or " failed" in line:
            print(line[:300], flush=True)
    print(f"red first, live: exit {r.returncode} (expected non-zero)", flush=True)
finally:
    for path, text in originals.items():
        open(path, "w").write(text)
